(function () {
  "use strict";

  /* ── Konfiguration – hier anpassen ─────────────────────────────────── */
  var CFG = {
    apiKey: "cmt2vdx1z00m40vmjcl2v42ny",
    apiBase: "https://api.bitpull.ai",
    language: "en",          /* "de" oder "en" */
    accentColor: "#7B61FF",
    headerLabel: "DEAI Summit",
    headerTitle: "Event Assistant",
    avatarUrl: "data:image/webp;base64,"  /* Bild-URL oder Data-URI, leer = Standard-Icon */
  };

  /* Hinweis EU AI Act (Art. 50): Die folgenden Texte kennzeichnen den
     Assistenten transparent als KI. Bitte den KI-Hinweis beim Anpassen
     der Texte beibehalten. */
  var ALL_TEXTS = {
    de: {
      aiBadge: "KI-Assistent",
      langHint: "Sie sprechen mit einem KI-Assistenten. Sprechen Sie einfach in Ihrer Sprache – die Antwort erfolgt automatisch in derselben Sprache.",
      start: "Gespräch starten",
      end: "Gespräch beenden",
      you: "Sie",
      assistant: "KI-Assistent",
      statusConnecting: "Verbinde…",
      statusConnected: "Bereit – sprechen Sie jetzt",
      statusUser: "Sie sprechen…",
      statusAgent: "KI-Assistent antwortet…",
      statusError: "Verbindungsfehler",
      micHttps: "Mikrofonzugriff erfordert HTTPS.",
      teasers: ["Fragen zum Programm?","Tickets oder Anfahrt?"]
    },
    en: {
      aiBadge: "AI assistant",
      langHint: "You are talking to an AI assistant. Just speak in your own language – it replies in the same language automatically.",
      start: "Start conversation",
      end: "End conversation",
      you: "You",
      assistant: "AI assistant",
      statusConnecting: "Connecting…",
      statusConnected: "Ready – speak now",
      statusUser: "You are speaking…",
      statusAgent: "AI assistant is replying…",
      statusError: "Connection error",
      micHttps: "Microphone access requires HTTPS.",
      teasers: ["Questions about the program?","Tickets or directions?"]
    }
  };
  var T = ALL_TEXTS[CFG.language] || ALL_TEXTS.de;

  /* ── Styles ─────────────────────────────────────────────────────────── */
  var css = "" +
    ".bpw-root{position:fixed;bottom:24px;right:24px;z-index:99999;display:flex;flex-direction:column;align-items:flex-end;gap:12px;pointer-events:none;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;}" +
    ".bpw-bubble{pointer-events:auto;position:relative;background:#fff;border:1px solid var(--bpw-accent-30);border-radius:12px;padding:12px 34px 12px 14px;max-width:230px;box-shadow:0 8px 32px rgba(0,0,0,.14);}" +
    ".bpw-bubble p{margin:0;font-size:.8rem;color:#555;line-height:1.5;}" +
    ".bpw-bubble-close{position:absolute;top:6px;right:6px;background:none;border:none;color:#999;cursor:pointer;padding:4px;line-height:0;}" +
    ".bpw-bubble-close:hover{color:#333;}" +
    ".bpw-panel{pointer-events:auto;width:320px;background:#fff;border:1px solid var(--bpw-accent-30);border-radius:16px;box-shadow:0 24px 64px rgba(0,0,0,.16);overflow:hidden;display:none;flex-direction:column;}" +
    ".bpw-panel.open{display:flex;}" +
    ".bpw-header{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--bpw-accent-15);}" +
    ".bpw-header-label{margin:0 0 2px;font-size:.55rem;font-weight:600;letter-spacing:.22em;text-transform:uppercase;color:var(--bpw-accent);}" +
    ".bpw-header-title{margin:0;font-size:1rem;font-weight:600;color:#1a1a1a;display:flex;align-items:center;gap:8px;}" +
    ".bpw-ai-badge{font-size:.55rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#666;border:1px solid #ddd;border-radius:999px;padding:2px 8px;}" +
    ".bpw-close{background:none;border:none;color:#999;cursor:pointer;padding:4px;line-height:0;}" +
    ".bpw-close:hover{color:#333;}" +
    ".bpw-avatar-wrap{position:relative;display:flex;align-items:center;justify-content:center;padding:28px 0 18px;cursor:pointer;}" +
    ".bpw-ring{position:absolute;width:120px;height:120px;border-radius:50%;border:1px solid var(--bpw-accent-30);opacity:0;}" +
    ".bpw-ring.active{opacity:1;animation:bpwRing 2.2s ease-out infinite;}" +
    ".bpw-ring2.active{animation-delay:1.1s;}" +
    "@keyframes bpwRing{0%{transform:scale(1);opacity:.5}100%{transform:scale(1.55);opacity:0}}" +
    ".bpw-avatar{width:96px;height:96px;border-radius:50%;border:2px solid var(--bpw-accent-40);overflow:hidden;position:relative;z-index:2;background:var(--bpw-accent-15);display:flex;align-items:center;justify-content:center;transition:border-color .3s;}" +
    ".bpw-avatar img{width:100%;height:100%;object-fit:cover;object-position:top;display:block;}" +
    ".bpw-avatar svg{width:38px;height:38px;color:var(--bpw-accent);}" +
    ".bpw-avatar.connecting{animation:bpwPulse 1.4s ease-in-out infinite;}" +
    ".bpw-avatar.live{border-color:var(--bpw-accent);}" +
    ".bpw-avatar.error{border-color:#e06060;}" +
    "@keyframes bpwPulse{0%,100%{box-shadow:0 0 0 0 var(--bpw-accent-30)}50%{box-shadow:0 0 0 12px rgba(0,0,0,0)}}" +
    ".bpw-wave{position:absolute;bottom:2px;left:50%;transform:translateX(-50%);display:flex;align-items:flex-end;gap:2px;height:32px;opacity:0;transition:opacity .3s;pointer-events:none;z-index:3;}" +
    ".bpw-wave.active{opacity:1;}" +
    ".bpw-bar{width:4px;border-radius:2px 2px 0 0;min-height:3px;background:linear-gradient(to top,var(--bpw-accent),var(--bpw-accent-30));}" +
    ".bpw-wave.user .bpw-bar{background:linear-gradient(to top,#64b4ff,rgba(100,180,255,.3));}" +
    ".bpw-status{display:flex;align-items:center;justify-content:center;gap:6px;padding-bottom:10px;}" +
    ".bpw-dot{width:6px;height:6px;border-radius:50%;background:var(--bpw-accent);}" +
    ".bpw-dot.connected{background:#4caf7d;}" +
    ".bpw-dot.error{background:#e06060;}" +
    ".bpw-dot.blink{animation:bpwBlink 1s ease-in-out infinite;}" +
    "@keyframes bpwBlink{0%,100%{opacity:1}50%{opacity:.3}}" +
    ".bpw-status-text{font-size:.65rem;letter-spacing:.1em;text-transform:uppercase;color:#666;}" +
    ".bpw-transcript{margin:0 14px 10px;max-height:170px;overflow-y:auto;border:1px solid var(--bpw-accent-15);border-radius:10px;padding:10px 12px;display:none;}" +
    ".bpw-transcript.has-entries{display:block;}" +
    ".bpw-entry{padding:6px 0;}" +
    ".bpw-entry+.bpw-entry{border-top:1px solid var(--bpw-accent-15);}" +
    ".bpw-entry-role{font-size:.6rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--bpw-accent);}" +
    ".bpw-entry.user .bpw-entry-role{color:#999;}" +
    ".bpw-entry-text{margin:3px 0 0;font-size:.82rem;line-height:1.55;color:#333;}" +
    ".bpw-controls{padding:0 14px 16px;display:flex;flex-direction:column;gap:10px;align-items:center;}" +
    ".bpw-hint{margin:0;font-size:.72rem;line-height:1.55;color:#666;text-align:center;padding:0 4px;}" +
    ".bpw-btn{width:100%;padding:12px 0;font-size:.68rem;font-weight:600;letter-spacing:.16em;text-transform:uppercase;border-radius:10px;cursor:pointer;transition:background .2s,border-color .2s;}" +
    ".bpw-btn-start{background:var(--bpw-accent);color:#fff;border:none;}" +
    ".bpw-btn-start:hover{filter:brightness(.92);}" +
    ".bpw-btn-stop{background:transparent;border:1px solid var(--bpw-accent-40);color:#666;}" +
    ".bpw-btn-stop:hover{border-color:var(--bpw-accent);color:#333;}" +
    ".bpw-error{margin:0;font-size:.7rem;color:#c05050;text-align:center;}" +
    ".bpw-trigger{pointer-events:auto;position:relative;display:flex;align-items:center;gap:8px;padding:11px 16px 11px 13px;background:#1a1a1a;border:1px solid var(--bpw-accent);border-radius:999px;color:#fff;cursor:pointer;box-shadow:0 8px 32px rgba(0,0,0,.3);transition:background .2s;}" +
    ".bpw-trigger:hover{background:#2a2a2a;}" +
    ".bpw-trigger-label{font-size:.62rem;font-weight:600;letter-spacing:.18em;text-transform:uppercase;}" +
    "@media (max-width:480px){.bpw-root{bottom:16px;right:16px}.bpw-panel{width:calc(100vw - 32px)}}";

  /* ── DOM ────────────────────────────────────────────────────────────── */
  var style = document.createElement("style");
  style.textContent = ":root{--bpw-accent:" + CFG.accentColor + ";--bpw-accent-40:" + hexA(CFG.accentColor, .4) + ";--bpw-accent-30:" + hexA(CFG.accentColor, .3) + ";--bpw-accent-15:" + hexA(CFG.accentColor, .15) + ";}" + css;
  document.head.appendChild(style);

  function hexA(hex, a) {
    var h = hex.replace("#", "");
    if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
    var n = parseInt(h, 16);
    return "rgba(" + ((n >> 16) & 255) + "," + ((n >> 8) & 255) + "," + (n & 255) + "," + a + ")";
  }

  function el(tag, cls, html) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (html != null) node.innerHTML = html;
    return node;
  }

  var ICON_MIC = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" stroke-linejoin="round" d="M12 18.75a6 6 0 006-6v-1.5m-6 7.5a6 6 0 01-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 01-3-3V4.5a3 3 0 116 0v8.25a3 3 0 01-3 3z"/></svg>';
  var ICON_X = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" d="M6 18L18 6M6 6l12 12"/></svg>';

  var root = el("div", "bpw-root");

  var bubble = el("div", "bpw-bubble");
  var bubbleText = el("p", "", "");
  var bubbleClose = el("button", "bpw-bubble-close", ICON_X);
  bubble.appendChild(bubbleText);
  bubble.appendChild(bubbleClose);
  bubble.style.display = "none";

  var panel = el("div", "bpw-panel");
  var header = el("div", "bpw-header");
  var headerInfo = el("div", "",
    "<p class='bpw-header-label'></p><h3 class='bpw-header-title'><span class='bpw-title-text'></span><span class='bpw-ai-badge'></span></h3>");
  headerInfo.querySelector(".bpw-header-label").textContent = CFG.headerLabel;
  headerInfo.querySelector(".bpw-title-text").textContent = CFG.headerTitle;
  headerInfo.querySelector(".bpw-ai-badge").textContent = T.aiBadge;
  var closeBtn = el("button", "bpw-close", ICON_X);
  header.appendChild(headerInfo);
  header.appendChild(closeBtn);

  var avatarWrap = el("div", "bpw-avatar-wrap");
  var ring1 = el("div", "bpw-ring");
  var ring2 = el("div", "bpw-ring bpw-ring2");
  var avatar = el("div", "bpw-avatar");
  if (CFG.avatarUrl) {
    var img = document.createElement("img");
    img.src = CFG.avatarUrl;
    img.alt = T.aiBadge;
    avatar.appendChild(img);
  } else {
    avatar.innerHTML = ICON_MIC;
  }
  var wave = el("div", "bpw-wave");
  var BAR_COUNT = 14;
  var bars = [];
  for (var i = 0; i < BAR_COUNT; i++) {
    var bar = el("span", "bpw-bar");
    bars.push(bar);
    wave.appendChild(bar);
  }
  avatarWrap.appendChild(ring1);
  avatarWrap.appendChild(ring2);
  avatarWrap.appendChild(avatar);
  avatarWrap.appendChild(wave);

  var status = el("div", "bpw-status");
  var dot = el("span", "bpw-dot");
  var statusText = el("span", "bpw-status-text");
  status.appendChild(dot);
  status.appendChild(statusText);
  status.style.display = "none";

  var transcript = el("div", "bpw-transcript");
  var controls = el("div", "bpw-controls");
  var hint = el("p", "bpw-hint");
  hint.textContent = T.langHint;
  var actionBtn = el("button", "bpw-btn bpw-btn-start");
  actionBtn.textContent = T.start;
  var errorMsg = el("p", "bpw-error");
  errorMsg.style.display = "none";
  controls.appendChild(hint);
  controls.appendChild(actionBtn);
  controls.appendChild(errorMsg);

  panel.appendChild(header);
  panel.appendChild(avatarWrap);
  panel.appendChild(status);
  panel.appendChild(transcript);
  panel.appendChild(controls);

  var trigger = el("button", "bpw-trigger");
  trigger.innerHTML = "<span style='display:flex;width:18px;height:18px'>" + ICON_MIC + "</span><span class='bpw-trigger-label'></span>";
  trigger.querySelector(".bpw-trigger-label").textContent = CFG.headerTitle;
  trigger.setAttribute("aria-label", T.aiBadge);

  root.appendChild(bubble);
  root.appendChild(panel);
  root.appendChild(trigger);
  document.body.appendChild(root);

  /* ── Teaser-Bubble ──────────────────────────────────────────────────── */
  var teaserIdx = 0;
  setTimeout(function () {
    if (!panel.classList.contains("open")) {
      bubbleText.textContent = T.teasers[teaserIdx % T.teasers.length];
      bubble.style.display = "block";
    }
  }, 4000);
  bubbleClose.addEventListener("click", function () { bubble.style.display = "none"; });

  /* ── State ──────────────────────────────────────────────────────────── */
  var core = null;
  var state = "idle";
  var waveRaf = null;
  var wavePhase = 0;

  function setState(next) {
    state = next;
    avatar.className = "bpw-avatar" +
      (next === "connecting" ? " connecting" : "") +
      (next === "connected" || next === "user" || next === "agent" ? " live" : "") +
      (next === "error" ? " error" : "");
    var live = next === "connected" || next === "user" || next === "agent" || next === "connecting";
    ring1.className = "bpw-ring" + (live ? " active" : "");
    ring2.className = "bpw-ring bpw-ring2" + (live ? " active" : "");
    status.style.display = next === "idle" ? "none" : "flex";
    hint.style.display = (next === "idle" || next === "error") ? "block" : "none";
    dot.className = "bpw-dot" +
      (next === "connected" ? " connected" : "") +
      (next === "error" ? " error" : "") +
      (next === "connecting" || next === "user" || next === "agent" ? " blink" : "");
    statusText.textContent =
      next === "connecting" ? T.statusConnecting :
      next === "connected" ? T.statusConnected :
      next === "user" ? T.statusUser :
      next === "agent" ? T.statusAgent :
      next === "error" ? T.statusError : "";
    if (next === "idle" || next === "error") {
      actionBtn.textContent = T.start;
      actionBtn.className = "bpw-btn bpw-btn-start";
    } else {
      actionBtn.textContent = T.end;
      actionBtn.className = "bpw-btn bpw-btn-stop";
    }
    errorMsg.style.display = next === "error" ? "block" : "none";
    setWave(next === "user" ? "user" : next === "agent" ? "agent" : null);
  }

  function setWave(mode) {
    if (!mode) {
      wave.className = "bpw-wave";
      if (waveRaf) { cancelAnimationFrame(waveRaf); waveRaf = null; }
      return;
    }
    wave.className = "bpw-wave active" + (mode === "user" ? " user" : "");
    if (waveRaf) return;
    var animate = function () {
      wavePhase += 0.09;
      for (var i = 0; i < BAR_COUNT; i++) {
        var h = Math.max(3, 14 + Math.sin(wavePhase + i * 0.45) * 9 + Math.sin(wavePhase * 1.7 + i * 0.9) * 6);
        bars[i].style.height = h + "px";
      }
      waveRaf = requestAnimationFrame(animate);
    };
    waveRaf = requestAnimationFrame(animate);
  }

  function upsertEntry(id, role, text) {
    var entry = transcript.querySelector("[data-id='" + id + "']");
    if (!entry) {
      entry = el("div", "bpw-entry " + role);
      entry.setAttribute("data-id", id);
      var roleEl = el("span", "bpw-entry-role");
      roleEl.textContent = role === "user" ? T.you : T.assistant;
      var textEl = el("p", "bpw-entry-text");
      entry.appendChild(roleEl);
      entry.appendChild(textEl);
      transcript.appendChild(entry);
      transcript.classList.add("has-entries");
    }
    entry.querySelector(".bpw-entry-text").textContent = text;
    transcript.scrollTop = transcript.scrollHeight;
  }

  /* ── Widget-Core laden ──────────────────────────────────────────────── */
  var corePromise = null;
  function loadCore() {
    if (corePromise) return corePromise;
    if (window.VoiceWidgetCore) return (corePromise = Promise.resolve());
    corePromise = new Promise(function (resolve, reject) {
      var s = document.createElement("script");
      s.src = CFG.apiBase + "/widget/voice-widget-core.js";
      s.onload = resolve;
      s.onerror = function () { reject(new Error("Widget core could not be loaded")); };
      document.head.appendChild(s);
    });
    return corePromise;
  }

  /* ── Verbinden / Trennen ────────────────────────────────────────────── */
  function connect() {
    if (state !== "idle" && state !== "error") return;
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      errorMsg.textContent = T.micHttps;
      setState("error");
      return;
    }
    transcript.innerHTML = "";
    transcript.classList.remove("has-entries");
    setState("connecting");

    loadCore()
      .then(function () {
        return fetch(CFG.apiBase + "/api/sessions", {
          method: "POST",
          headers: { "Authorization": "Bearer " + CFG.apiKey, "Content-Type": "application/json" },
          body: JSON.stringify({ language: CFG.language })
        });
      })
      .then(function (res) {
        if (!res.ok) throw new Error("Session request failed (" + res.status + ")");
        return res.json();
      })
      .then(function (session) {
        core = new window.VoiceWidgetCore({
          onConnect: function () { setState("connected"); },
          onDisconnect: function () { if (state !== "error") setState("idle"); },
          onStatusChange: function (s) {
            if (s === "initializing" || s === "connecting") setState("connecting");
            else if (s === "connected") setState("connected");
            else if (s === "disconnected" && state !== "idle" && state !== "error") setState("idle");
            else if (s === "error") setState("error");
          },
          onTranscription: function (data) {
            if (!data || !data.text) return;
            var pid = typeof data.participantIdentity === "string"
              ? data.participantIdentity
              : (data.participantIdentity && (data.participantIdentity.identity || data.participantIdentity.sid)) || "";
            var isAgent = data.role === "agent" || data.role === "assistant" || String(pid).indexOf("agent") !== -1;
            var id = (isAgent ? "agent-" : "user-") + (data.segmentId || Date.now());
            upsertEntry(id, isAgent ? "assistant" : "user", data.text);
            if (data.isFinal) setState("connected");
            else setState(isAgent ? "agent" : "user");
          },
          onError: function (err) {
            errorMsg.textContent = (err && err.message) || T.statusError;
            setState("error");
          }
        });
        return core.connect({ wsUrl: session.wsUrl, token: session.token, sessionId: session.sessionId });
      })
      .catch(function (err) {
        if (core) { try { core.disconnect(); } catch (e) { /* ignore */ } core = null; }
        errorMsg.textContent = (err && err.message) || T.statusError;
        setState("error");
      });
  }

  function disconnect() {
    if (core) { try { core.disconnect(); } catch (e) { /* ignore */ } core = null; }
    errorMsg.style.display = "none";
    setState("idle");
  }

  /* ── Events ─────────────────────────────────────────────────────────── */
  actionBtn.addEventListener("click", function () {
    if (state === "idle" || state === "error") connect(); else disconnect();
  });
  avatarWrap.addEventListener("click", function () {
    if (state === "idle" || state === "error") connect(); else disconnect();
  });
  trigger.addEventListener("click", function () {
    bubble.style.display = "none";
    panel.classList.toggle("open");
    if (!panel.classList.contains("open") && state !== "idle") disconnect();
  });
  closeBtn.addEventListener("click", function () {
    panel.classList.remove("open");
    if (state !== "idle") disconnect();
  });

  setState("idle");
})();
